// Freeze user instructions for the lifetime of each live session.
export function createUserPromptReader(readSettings) {
  const snapshots = new WeakMap();
  const read = (context, visiting = new Set()) => {
    const session = context.agent?.session ?? context.agent ?? context.scope;
    if (session && typeof session === "object") {
      if (!snapshots.has(session)) {
        // A live child inherits the exact parent's frozen working instructions,
        // even if settings changed while that parent's task was running.
        const parentId = context.agent?.session?.header?.parentSession;
        const parent = parentId && context.agent?.ctx?.agents?.get(parentId);
        visiting.add(session);
        const inherited = parent && !visiting.has(parent.session) ? read({ agent: parent }, visiting) : readSettings()?.text ?? "";
        snapshots.set(session, inherited);
      }
      return snapshots.get(session);
    }
    return readSettings()?.text ?? "";
  };
  return read;
}
